{"pr":["Par Rapport quotidien:true","Cumulé sur 5 Rapports:false"],"v":["","","120 min","4,4 s"],"f":"DIV Reporting manuel déclaré et Chaîne mesur outline:solid 2px"}
### Ran Playwright code
```js
await (async (page) => { await page.getByRole('button',{name:'Cumulé sur 5 Rapports'}).click(); await page.waitForTimeout(1500); const pr=await page.locator('button[aria-pressed]').evaluateAll(l=>l.map(b=>b.innerText+':'+b.getAttribute('aria-pressed'))); const v=await page.locator('main p').allInnerTexts(); await page.keyboard.press('Tab'); const f=await page.evaluate(()=>{const a=document.activeElement;return a.tagName+' '+a.innerText.slice(0,40)+' outline:'+getComputedStyle(a).outlineStyle+' '+getComputedStyle(a).outlineWidth}); return {pr,v:v.slice(2,6),f}; })(page);
```

